function validate([nums]) {
  if (nums.length < 3 || nums.length > 1e5) return 'nums needs 3 to 10^5 values.';
  if (nums.some(v => !Number.isInteger(v) || v < 1 || v > 1e9)) return 'Each value is an integer between 1 and 10^9.';
  return null;
}

