function largestPerimeter(nums) {
  nums.sort((a, b) => a - b);
  let prefix = 0;
  let best = -1;

  for (let i = 0; i < nums.length; i++) {
    if (i >= 2 && prefix > nums[i]) {
      best = prefix + nums[i];
    }
    prefix += nums[i];
  }
  return best;
}

