function largestPerimeter(nums) {
  const n = nums.length;
  let best = -1;
  for (let mask = 0; mask < (1 << n); mask++) {
    const sides = nums.filter((_, i) => mask & (1 << i));
    if (sides.length < 3) continue;
    const longest = Math.max(...sides);
    const total = sides.reduce((s, v) => s + v, 0);
    if (total - longest > longest && total > best) best = total;
  }
  return best;
}

