function generate(rand, size) {
  const n = size === 'large' ? 1500 + Math.floor(rand() * 501) : 3 + Math.floor(rand() * 8);
  const mode = rand();
  const nums = [];
  for (let i = 0; i < n; i++) {
    if (mode < 0.3) {
      // Roughly doubling lengths, so many prefixes cannot close a polygon.
      const base = Math.min(1e9, 2 ** Math.min(29, i + Math.floor(rand() * 3)));
      nums.push(Math.max(1, Math.min(1e9, base - Math.floor(rand() * 2))));
    } else if (mode < 0.6) {
      // Many short sides plus a few very long ones the short ones cannot balance.
      const spike = rand() < (size === 'large' ? 0.01 : 0.25);
      nums.push(spike ? 1 + Math.floor(rand() * 1e9) : 1 + Math.floor(rand() * (size === 'large' ? 1000 : 6)));
    } else {
      const cap = size === 'large' ? 1e9 : rand() < 0.5 ? 5 : 30;
      nums.push(1 + Math.floor(rand() * cap));
    }
  }
  for (let i = nums.length - 1; i > 0; i--) {
    const j = Math.floor(rand() * (i + 1));
    [nums[i], nums[j]] = [nums[j], nums[i]];
  }
  return [nums];
}
